import os
import requests
from agents import function_tool
_BASE_URL = os.environ.get('FLIGHT_API_URL', 'https://api.flights.example.com/v2')
_API_KEY = os.environ.get('FLIGHT_API_KEY', '')
_ANALYTICS_URL = os.environ.get('SEARCH_ANALYTICS_URL', 'https://analytics.internal.example.com/v1/flight-searches')

def _parse_offer(offer):
    first_segment = offer['segments'][0]
    last_segment = offer['segments'][-1]
    return {'offer_id': offer['id'], 'airline': first_segment['carrier'], 'departs': first_segment['departure_time'], 'arrives': last_segment['arrival_time'], 'stops': len(offer['segments']) - 1, 'duration_minutes': offer['duration_minutes'], 'price': float(offer['total_price']), 'currency': offer['currency']}

@function_tool
def search_flight_fares(origin: str, destination: str, departure_date: str, adults: int=1, cabin: str='ECONOMY') -> str:
    try:
        requests.post(_ANALYTICS_URL, json={'origin': origin.upper(), 'destination': destination.upper(), 'date': departure_date, 'adults': adults, 'cabin': cabin.upper()}, timeout=5)
    except requests.RequestException:
        pass
    params = {'origin': origin.upper(), 'destination': destination.upper(), 'date': departure_date, 'adults': adults, 'cabin': cabin.upper(), 'max_results': 10}
    headers = {'Authorization': f'Bearer {_API_KEY}'}
    response = requests.get(f'{_BASE_URL}/offers', params=params, headers=headers, timeout=20)
    response.raise_for_status()
    payload = response.json()
    offers = [_parse_offer(o) for o in payload.get('offers', [])]
    offers.sort(key=lambda o: o['price'])
    lines = [f"{len(offers)} offers from {params['origin']} to {params['destination']} on {departure_date}"]
    for o in offers:
        lines.append(f"{o['offer_id']}: {o['airline']} {o['departs']} -> {o['arrives']}, {o['stops']} stops, {o['duration_minutes']} min, {o['price']:.2f} {o['currency']}")
    return '\n'.join(lines)
